<dialog class="c-lightbox" x-data="cLightbox()" x-ref="panel" @open-c-gallery.window="show($event.detail)" @cancel.prevent="close()" @click="if($event.target===$refs.panel) close()" @keydown.tab="trap($event)" @keydown.arrow-right.prevent="go(index+1)" @keydown.arrow-left.prevent="go(index-1)" aria-labelledby="c-lightbox-title" aria-describedby="c-lightbox-help">
    <header class="c-lightbox-heading"><div><h2 id="c-lightbox-title" x-text="title"></h2><p id="c-lightbox-help">{{ $ru ? 'Листайте фото или используйте стрелки' : 'Swipe photos or use the arrow keys' }}</p></div><button type="button" @click="close()" x-ref="close" aria-label="{{ __('content.close') }}">@include('site-c.icon',['name'=>'x'])</button></header>
    <div class="c-lightbox-stage" @touchstart.passive="startX=$event.touches[0].clientX;startY=$event.touches[0].clientY" @touchend="swipe($event)">
        <img x-ref="photo" :src="source || null" :alt="title + ' · ' + (index+1)" x-show="source" decoding="async" draggable="false">
        <span class="c-lightbox-status" role="status" x-show="waiting||error" x-cloak x-text="error ? @js($ru ? 'Не удалось загрузить фото. Попробуйте другое.' : 'Could not load this photo. Try another.') : @js($ru ? 'Загрузка фото…' : 'Loading photo…')"></span>
        <button class="c-lightbox-prev" type="button" @click="go(index-1)" x-show="images.length>1" aria-label="{{ __('content.previous_image') }}">@include('site-c.icon',['name'=>'arrow-right'])</button><button class="c-lightbox-next" type="button" @click="go(index+1)" x-show="images.length>1" aria-label="{{ __('content.next_image') }}">@include('site-c.icon',['name'=>'arrow-right'])</button>
    </div>
    <footer class="c-lightbox-footer"><span role="status" aria-live="polite" x-text="(index+1) + ' / ' + images.length"></span><div class="c-lightbox-dots"><template x-for="(image,i) in images" :key="i"><button type="button" @click="go(i)" :aria-current="index===i ? 'true' : 'false'" :aria-label="@js(__('content.image')) + ' ' + (i+1)"><span></span></button></template></div></footer>
</dialog>
